-- payment-service: billing profiles, cards, one tuition invoice per student per quarter with one line per enrolled subject ($320)
-- Ask 46 baseline seed, exported from the running stack by scripts/export_seed.py (Flyway reset). Edit by hand or re-export.

SELECT setval(pg_get_serial_sequence('billing_profile', 'id'), COALESCE((SELECT max(id) FROM billing_profile), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('payment_method', 'id'), COALESCE((SELECT max(id) FROM payment_method), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('invoice', 'id'), COALESCE((SELECT max(id) FROM invoice), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('invoice_line', 'id'), COALESCE((SELECT max(id) FROM invoice_line), 0) + 1, false);
